import{_ as i,C as a,o as n,c as o,E as r,a2 as s}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"A Digital Employee Is Not Done Until Completion Is Independently Accepted","description":"","frontmatter":{"title":"A Digital Employee Is Not Done Until Completion Is Independently Accepted","date":"2026-08-05","column":"digital-employee","category":"daily","summary":"Computer-use agents need a completion contract that separates process evidence, business outcome and failure classification. The worker may claim completion, but it must not accept its own claim.","item_id":"Q-20260805-12","source_research_object":"research/analysis/Q-20260805-12-verifiable-completion.md","source_reading_result":"research/reading/Q-20260805-12-verifiable-completion.md","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep","cover":"/assets/covers/verifiable-completion-cover-v2.jpg"},"headers":[],"relativePath":"en/digital-employee/2026-08-05-verifiable-completion.md","filePath":"en/digital-employee/2026-08-05-verifiable-completion.md","lastUpdated":1787407830000}'),c={name:"en/digital-employee/2026-08-05-verifiable-completion.md"};function l(d,e,p,m,u,h){const t=a("ArticleCover");return n(),o("div",null,[r(t,{image:"/assets/covers/verifiable-completion-cover-v2.jpg",kicker:"Digital Employee · Daily Research",title:"A Digital Employee Is Not Done Until Completion Is Independently Accepted",summary:"Computer-use agents need a completion contract that separates process evidence, business outcome and failure classification. The worker may claim completion, but it must not accept its own claim.",version:"Q-20260805-12",status:"Daily Runtime V5 · 2026-08-05",languageHref:"/zh/digital-employee/2026-08-05-verifiable-completion",languageLabel:"中文"}),e[0]||(e[0]=s('<h1 id="a-digital-employee-is-not-done-until-completion-is-independently-accepted" tabindex="-1">A Digital Employee Is Not Done Until Completion Is Independently Accepted <a class="header-anchor" href="#a-digital-employee-is-not-done-until-completion-is-independently-accepted" aria-label="Permalink to &quot;A Digital Employee Is Not Done Until Completion Is Independently Accepted&quot;">​</a></h1><p>Computer-use agents need a completion contract that separates process evidence, business outcome and failure classification. The worker may claim completion, but it must not accept its own claim.</p><h2 id="core-judgment" tabindex="-1">Core judgment <a class="header-anchor" href="#core-judgment" aria-label="Permalink to &quot;Core judgment&quot;">​</a></h2><p>Completion is a governed claim, not the last action, a final screenshot or a model-generated sentence.</p><h2 id="why-this-is-not-a-point-feature" tabindex="-1">Why this is not a point feature <a class="header-anchor" href="#why-this-is-not-a-point-feature" aria-label="Permalink to &quot;Why this is not a point feature&quot;">​</a></h2><p>A final screenshot can show an outcome artifact without proving required steps, side-effect limits or business authority. A process score can show execution quality without proving the requested business state. A failure label can assign responsibility without providing retry safety. These are separate claims and need separate evidence.</p><h2 id="minimum-deployable-architecture" tabindex="-1">Minimum deployable architecture <a class="header-anchor" href="#minimum-deployable-architecture" aria-label="Permalink to &quot;Minimum deployable architecture&quot;">​</a></h2><p>Use a versioned Completion Claim containing the expected outcome, process evidence, deterministic state readback, optional learned-verifier advice, failure and side-effect classification, and an independent acceptance decision. Preserve disagreement instead of forcing a binary answer.</p><h2 id="boundaries-and-counter-evidence" tabindex="-1">Boundaries and counter-evidence <a class="header-anchor" href="#boundaries-and-counter-evidence" aria-label="Permalink to &quot;Boundaries and counter-evidence&quot;">​</a></h2><p>The supporting research is web-task specific, uses a 246-trajectory benchmark and still reports an 8% external false-positive rate. It does not demonstrate rollback, compensation, transactionality or enterprise incident reduction.</p><h2 id="engineering-conclusion" tabindex="-1">Engineering conclusion <a class="header-anchor" href="#engineering-conclusion" aria-label="Permalink to &quot;Engineering conclusion&quot;">​</a></h2><p>Adopt the separation pattern first: claimant, evidence contract, verifier and acceptor. Treat learned verification as advice alongside deterministic business checks and required human authority.</p><h2 id="visualization-note" tabindex="-1">Visualization note <a class="header-anchor" href="#visualization-note" aria-label="Permalink to &quot;Visualization note&quot;">​</a></h2><p>The diagram represents control boundaries and state relationships. It does not present experimental results or invent quantitative comparisons absent from the Research Object.</p><h2 id="evidence-and-citations" tabindex="-1">Evidence and citations <a class="header-anchor" href="#evidence-and-citations" aria-label="Permalink to &quot;Evidence and citations&quot;">​</a></h2><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260805-12-verifiable-completion.md" target="_blank" rel="noreferrer">Research Object</a>: the sole analytical input, including judgments, uncertainty, counter-evidence and engineering implications.</li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260805-12-verifiable-completion.md" target="_blank" rel="noreferrer">Reading Result</a>: the evidence boundary and source-trace record behind the Research Object.</li></ol>',16))])}const g=i(c,[["render",l]]);export{f as __pageData,g as default};
